steps.code:
query CartValidationsGenerateRunInput {
  buyerJourney {
    step
  }
  cart {
    cost {
      subtotalAmount {
        amount
      }
    }
    buyerIdentity {
      purchasingCompany {
        company {
          id
        }
      }
    }
    lines {
      quantity
      merchandise {
        __typename
        ... on ProductVariant {
          sku
          product {
            title
          }
        }
      }
    }
  }
  validation {
    metafield(namespace: "$app:config", key: "min_order") {
      value
    }
  }
}

# shopify.extension.toml — variáveis usadas na input query
[extensions.input.variables]
namespace = "$app:config"
key = "min_order"

# input query que usa as variáveis
query Input($namespace: String!, $key: String!) {
  validation {
    metafield(namespace: $namespace, key: $key) {
      jsonValue
    }
  }
}

# grava a configuração da Function (Admin API)
mutation SetConfig($id: ID!, $value: String!) {
  metafieldsSet(metafields: [{
    ownerId: $id,
    namespace: "$app:config",
    key: "min_order",
    type: "number_decimal",
    value: $value
  }]) {
    metafields { id }
    userErrors { field message }
  }
}
